#include <string>
#include <algorithm>
#include <iostream>

int main() {
    std::string s = "hello world";

    // Random access iterator arithmetic
    auto it = s.begin() + 6;
    std::cout << *it << std::endl; // prints 'w'

    // Use with RA-required algorithm (e.g., sort)
    std::sort(s.begin(), s.end()); 

    // Using push_back via back_inserter (for generic algorithm compatibility)
    std::string target;
    std::copy(s.begin(), s.end(), std::back_inserter(target));
}
